export type NormalizedMovie = {
  id: string;
  title: string;
  originalTitle?: string;
  year: number;
  rating: number;
  duration: number;
  genres: string[];
  description: string;
  director: string;
  cast: string[];
  poster: string;
  backdrop: string;
  type: 'movie' | 'series' | 'animation';
  slug?: string;
  subjectId?: string;
  badge?: string;
  quality?: string[];
};

function toNumber(value: unknown, fallback = 0) {
  const asNumber = Number(value);
  return Number.isFinite(asNumber) ? asNumber : fallback;
}

function getString(value: unknown, fallback = '') {
  return typeof value === 'string' ? value : fallback;
}

export function normalizeMovieboxItem(raw: Record<string, any>, fallbackType: NormalizedMovie['type'] = 'movie'): NormalizedMovie {
  const title = getString(raw.title || raw.name, 'Untitled');
  const rating = raw.imdbRatingValue ?? raw.rating ?? raw.vote_average ?? 0;
  const year = toNumber(raw.releaseDate?.slice(0, 4) || raw.year || raw.publishYear, new Date().getFullYear());
  const genres = Array.isArray(raw.genres)
    ? raw.genres.map((g: any) => getString(g?.name || g)).filter(Boolean)
    : Array.isArray(raw.genre)
      ? raw.genre.map((g: any) => getString(g?.name || g)).filter(Boolean)
      : getString(raw.genre, '').split(',').map((part) => part.trim()).filter(Boolean);

  const cast = Array.isArray(raw.cast)
    ? raw.cast.map((g: any) => getString(g?.name || g)).filter(Boolean)
    : Array.isArray(raw.casts)
      ? raw.casts.map((g: any) => getString(g?.name || g)).filter(Boolean)
      : [];

  const poster = getString(raw.cover?.url || raw.poster_url || raw.poster || raw.image || raw.cover, '');
  const backdrop = getString(raw.backdrop?.url || raw.backdrop || poster, poster);
  const description = getString(raw.description || raw.synopsis || raw.story || raw.summary, 'No description available.');

  return {
    id: String(raw.subjectId || raw.id || `${title}-${year}`),
    title,
    originalTitle: getString(raw.originalTitle || raw.original_title, title),
    year,
    rating: toNumber(rating, 0),
    duration: toNumber(raw.duration || raw.runtime || raw.length, 0),
    genres: genres.length ? genres : ['General'],
    description,
    director: getString(raw.director || raw.directorName || raw.creator || '', ''),
    cast: cast.length ? cast : ['Unknown'],
    poster,
    backdrop,
    type: (raw.type || fallbackType || 'movie') as NormalizedMovie['type'],
    slug: getString(raw.detailPath || raw.slug, ''),
    subjectId: String(raw.subjectId || raw.subject_id || raw.id || ''),
    badge: getString(raw.corner || raw.badge, ''),
    quality: Array.isArray(raw.quality) ? raw.quality.map((q: any) => String(q)) : undefined,
  };
}

export function normalizeMovieboxPayload(payload: any) {
  const sections = Array.isArray(payload?.sections) ? payload.sections : [];

  return {
    sections: sections.map((section: any) => ({
      section: String(section?.section || 'Featured'),
      count: Number(section?.count || section?.items?.length || 0),
      items: Array.isArray(section?.items) ? section.items.map((item: any) => normalizeMovieboxItem(item)) : [],
    })),
    items: Array.isArray(payload?.items) ? payload.items.map((item: any) => normalizeMovieboxItem(item)) : [],
    total: Number(payload?.total || 0),
  };
}
