import { NextRequest, NextResponse } from 'next/server';
import { getCached, setCached } from '@/lib/moviebox-cache';
import { normalizeMovieboxPayload } from '@/lib/moviebox-normalizer';

const MOVIEBOX_API_URL = process.env.MOVIEBOX_API_URL ?? 'http://127.0.0.1:8000';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> },
) {
  const { path } = await params;
  const url = new URL(request.url);
  const resourcePath = path.join('/');
  const cacheKey = `moviebox:proxy:${resourcePath}:${url.search}`;
  const cached = getCached<any>(cacheKey);

  if (cached) {
    return NextResponse.json(cached);
  }

  const upstream = new URL(`/${resourcePath}${url.search}`, MOVIEBOX_API_URL);

  try {
    const response = await fetch(upstream.toString(), {
      headers: {
        Accept: 'application/json',
      },
      cache: 'no-store',
    });

    const contentType = response.headers.get('content-type') || 'application/json';
    const payloadText = await response.text();

    if (!response.ok) {
      return NextResponse.json(
        { error: payloadText || 'Moviebox upstream request failed' },
        { status: response.status },
      );
    }

    const normalizedPayload =
      resourcePath === 'home' || resourcePath === 'search' || resourcePath.startsWith('movies') || resourcePath.startsWith('tv-series') || resourcePath.startsWith('animation')
        ? normalizeMovieboxPayload(JSON.parse(payloadText || '{}'))
        : JSON.parse(payloadText || '{}');

    setCached(cacheKey, normalizedPayload, resourcePath === 'home' || resourcePath === 'search' ? 90_000 : 180_000);

    if (contentType.includes('application/json')) {
      return new NextResponse(JSON.stringify(normalizedPayload), {
        status: 200,
        headers: {
          'content-type': 'application/json; charset=utf-8',
          'cache-control': 'public, max-age=60, s-maxage=120',
        },
      });
    }

    return new NextResponse(payloadText, {
      status: 200,
      headers: {
        'content-type': contentType,
        'cache-control': 'no-store',
      },
    });
  } catch (error) {
    return NextResponse.json(
      {
        error: error instanceof Error ? error.message : 'Failed to reach Moviebox backend',
      },
      { status: 502 },
    );
  }
}
